package com.smartmart.inventory.service;
import com.smartmart.common.exception.BusinessException; import com.smartmart.inventory.dto.*; import com.smartmart.inventory.entity.Inventory; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.product.repository.ProductRepository; import lombok.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class InventoryService { private final InventoryRepository repo; private final ProductRepository products;
 @Transactional public InventoryResponse create(InventoryRequest r){ if(repo.findByProductId(r.getProductId()).isPresent()) throw BusinessException.conflict("Inventory already exists for this product"); return map(repo.save(Inventory.builder().product(products.findById(r.getProductId()).orElseThrow(()->BusinessException.notFound("Product not found"))).quantity(r.getQuantity()).reorderLevel(r.getReorderLevel()).expiryDate(r.getExpiryDate()).discountPercentage(r.getDiscountPercentage()).build())); }
 @Transactional(readOnly=true) public List<InventoryResponse> all(){return repo.findAll().stream().map(this::map).toList();} @Transactional(readOnly=true) public InventoryResponse one(Long id){return map(get(id));} @Transactional(readOnly=true) public InventoryResponse product(Long id){return map(repo.findByProductId(id).orElseThrow(()->BusinessException.notFound("Inventory not found")));}
 @Transactional public InventoryResponse update(Long id, InventoryRequest r){ Inventory i=get(id); i.setProduct(products.findById(r.getProductId()).orElseThrow(()->BusinessException.notFound("Product not found"))); i.setQuantity(r.getQuantity()); i.setReorderLevel(r.getReorderLevel()); i.setExpiryDate(r.getExpiryDate()); i.setDiscountPercentage(r.getDiscountPercentage()); return map(i); }
 @Transactional public void delete(Long id){repo.delete(get(id));} @Transactional(readOnly=true) public List<InventoryResponse> low(){return repo.findLowStock().stream().map(this::map).toList();} @Transactional(readOnly=true) public List<InventoryResponse> expiring(){return repo.findByExpiryDateBetween(LocalDate.now(),LocalDate.now().plusDays(30)).stream().map(this::map).toList();} @Transactional(readOnly=true) public List<InventoryResponse> discounted(){return repo.findByDiscountPercentageGreaterThan(java.math.BigDecimal.ZERO).stream().map(this::map).toList();}
 public Inventory get(Long id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Inventory not found"));} public InventoryResponse map(Inventory i){return InventoryResponse.builder().id(i.getId()).productId(i.getProduct().getId()).productName(i.getProduct().getName()).quantity(i.getQuantity()).reorderLevel(i.getReorderLevel()).expiryDate(i.getExpiryDate()).discountPercentage(i.getDiscountPercentage()).build();}
}
